pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {SqrtPriceMath} from "@uniswap/v4-core/src/libraries/SqrtPriceMath.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {ModifyLiquidityParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {StrategyTreasury} from "./StrategyTreasury.sol";
import {StrategyV4Hook} from "./StrategyV4Hook.sol";

/// @notice One-time launch that permanently locks the full token allocation in a one-sided position.
/// @dev At the fixed upper tick, the position initially contains token1 only. Buys supply
/// its native liquidity. The required 2 wei stays locked here, not in pool reserves.
/// The fixed tick implies ~25 ETH initial FDV for a 1 billion / 18-decimal token supply;
/// a different supply changes that valuation. No withdrawals, LP removal, or fee collection.
contract StrategyTokenOnlyInitializer is IUnlockCallback {
    using SafeERC20 for IERC20;
    using BalanceDeltaLibrary for BalanceDelta;

    uint256 private constant Q96 = 1 << 96;
    uint256 public constant NATIVE_SEED = 2;
    uint256 public constant MIN_CONSUMPTION_BPS = 9_900;
    int24 public constant TICK_LOWER = -887220;
    int24 public constant TICK_UPPER = 175020;
    bytes32 public constant POSITION_SALT = bytes32(0);

    address public immutable launchAuthority;
    bool public initialized;
    address public treasury;
    StrategyV4Hook public hook;
    IPoolManager public poolManager;
    IERC20 public token;
    uint128 public lockedLiquidity;
    uint256 public tokensDeposited;
    uint256 public constant nativeDeposited = 0;
    bool private _callbackPending;

    error Unauthorized();
    error AlreadyInitialized();
    error InvalidConfiguration();
    error InvalidSeed();
    error InvalidInitialPrice();
    error UnexpectedCallback();
    error UnexpectedLiquidityDelta();

    event Initialized(
        address indexed treasury,
        address indexed hook,
        address indexed token,
        uint160 sqrtPriceX96,
        uint128 liquidity,
        uint256 tokensDeposited
    );

    constructor(address launchAuthority_) {
        if (launchAuthority_ == address(0)) revert InvalidConfiguration();
        launchAuthority = launchAuthority_;
    }

    function initialSqrtPriceX96() public pure returns (uint160) {
        return TickMath.getSqrtPriceAtTick(TICK_UPPER);
    }

    function initialize(address treasury_, address hook_, uint160 sqrtPriceX96) external payable {
        if (msg.sender != launchAuthority) revert Unauthorized();
        if (initialized) revert AlreadyInitialized();
        if (msg.value != NATIVE_SEED) revert InvalidSeed();
        if (sqrtPriceX96 != initialSqrtPriceX96()) revert InvalidInitialPrice();
        if (treasury_.code.length == 0 || hook_.code.length == 0) revert InvalidConfiguration();
        initialized = true;
        StrategyTreasury targetTreasury = StrategyTreasury(payable(treasury_));
        StrategyV4Hook targetHook = StrategyV4Hook(payable(hook_));
        IERC20 targetToken = IERC20(targetHook.token());
        IPoolManager manager = targetHook.poolManager();
        if (
            targetHook.poolInitializer() != address(this) || targetHook.treasury() != treasury_
                || targetTreasury.initializer() != address(this)
                || address(targetTreasury.token()) != address(targetToken)
                || address(targetTreasury.hook()) != address(0)
                || address(manager).code.length == 0 || address(targetToken).code.length == 0
        ) revert InvalidConfiguration();
        PoolKey memory key = targetHook.getPoolKey();
        if (
            Currency.unwrap(key.currency0) != address(0) || Currency.unwrap(key.currency1) != address(targetToken)
                || address(key.hooks) != hook_ || key.tickSpacing != 60 || key.fee != 0
        ) revert InvalidConfiguration();
        uint256 supply = targetToken.totalSupply();
        if (supply == 0 || supply > uint256(uint128(type(int128).max))
            || targetToken.balanceOf(address(this)) != supply) revert InvalidSeed();
        uint160 lower = TickMath.getSqrtPriceAtTick(TICK_LOWER);
        uint256 liquidity = Math.mulDiv(supply, Q96, sqrtPriceX96 - lower);
        if (liquidity == 0 || liquidity > uint256(uint128(type(int128).max))) revert InvalidSeed();
        uint256 amount1 = SqrtPriceMath.getAmount1Delta(lower, sqrtPriceX96, uint128(liquidity), true);
        if (amount1 > supply || amount1 < Math.mulDiv(supply, MIN_CONSUMPTION_BPS, 10_000, Math.Rounding.Ceil)) {
            revert InvalidSeed();
        }
        treasury = treasury_;
        hook = targetHook;
        poolManager = manager;
        token = targetToken;
        lockedLiquidity = uint128(liquidity);
        tokensDeposited = amount1;

        targetTreasury.initializeHook(hook_);
        manager.initialize(key, sqrtPriceX96);
        _callbackPending = true;
        manager.unlock(bytes(""));
        if (_callbackPending) revert UnexpectedCallback();
        emit Initialized(treasury_, hook_, address(targetToken), sqrtPriceX96, uint128(liquidity), amount1);
    }

    function unlockCallback(bytes calldata) external returns (bytes memory) {
        if (msg.sender != address(poolManager) || !_callbackPending) revert UnexpectedCallback();
        _callbackPending = false;
        (BalanceDelta delta,) = poolManager.modifyLiquidity(
            hook.getPoolKey(),
            ModifyLiquidityParams({
                tickLower: TICK_LOWER,
                tickUpper: TICK_UPPER,
                liquidityDelta: int256(uint256(lockedLiquidity)),
                salt: POSITION_SALT
            }),
            bytes("")
        );
        if (delta.amount0() != 0 || int256(delta.amount1()) != -int256(tokensDeposited)) {
            revert UnexpectedLiquidityDelta();
        }
        poolManager.sync(Currency.wrap(address(token)));
        token.safeTransfer(address(poolManager), tokensDeposited);
        poolManager.settle();
        return bytes("");
    }
}
","keccak256":"0xb25aff5841d5e8fe82eb0a4cd49792374a64e730941b09682fbd889b9c81bd18","license":"MIT"},"contracts/StrategyTreasury.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IRevisionedNFTMarket} from "./interfaces/IRevisionedNFTMarket.sol";

interface IStrategyExecutor {
    function token() external view returns (address);
    function treasury() external view returns (address);
    function executeBuyback() external payable returns (uint256);
}

interface IBurnableStrategyToken is IERC20 {
    function burn(uint256 amount) external;
}

/// @notice Custody without an owner. Only a paid, fixed-price sale can release a purchased NFT.
/// @dev Optional spend caps are loss bounds, not fair-value proofs. Zero disables a cap.
contract StrategyTreasury is IERC721Receiver, ReentrancyGuard {
    struct Config {
        address token;
        address collection;
        address market;
        address initializer;
        uint256 firstTokenId;
        uint256 tokenCount;
        uint256 maxPurchasePrice;
        uint256 maxSpendPerEpoch;
        uint32 epochDuration;
        uint32 minPurchaseInterval;
        uint32 maxInventory;
        uint256 maxBuybackAmount;
        uint32 minBuybackInterval;
    }

    struct Position { uint256 cost; uint256 ask; }
    struct Quote { uint256 tokenId; address seller; uint256 price; uint256 revision; bool found; }

    IBurnableStrategyToken public immutable token;
    IERC721 public immutable collection;
    IRevisionedNFTMarket public immutable market;
    address public immutable initializer;
    uint256 public immutable firstTokenId;
    uint256 public immutable tokenCount;
    uint256 public immutable maxPurchasePrice;
    uint256 public immutable maxSpendPerEpoch;
    uint32 public immutable epochDuration;
    uint32 public immutable minPurchaseInterval;
    uint32 public immutable maxInventory;
    uint256 public immutable maxBuybackAmount;
    uint32 public immutable minBuybackInterval;
    uint256 public constant RESALE_BPS = 11_000;

    // Set once by the atomic launch initializer. There is no replacement or reset.
    IStrategyExecutor public hook;
    mapping(uint256 => Position) public positions;
    uint256 public acquisitionBalance;
    uint256 public buybackBalance;
    uint256 public inventoryCount;
    uint256 public totalFeesReceived;
    uint256 public totalAcquisitionSpent;
    uint256 public totalSaleProceeds;
    uint256 public totalBuybackSpent;
    uint256 public totalTokensBurned;
    uint256 public spentInEpoch;
    uint256 public spendEpoch;
    uint256 public nextPurchaseAt;
    uint256 public nextBuybackAt;
    bool private acquiring;
    uint256 private pendingTokenId;

    error InvalidConfig();
    error Unauthorized();
    error AlreadyInitialized();
    error Inactive();
    error NoEligibleListing();
    error StaleQuote();
    error PurchaseLimit();
    error Cooldown();
    error InvalidNFT();
    error InvalidPayment();
    error InvalidBuyback();

    event Initialized(address indexed hook);
    event FeesReceived(uint256 amount);
    event AcquisitionFunded(address indexed sender, uint256 amount);
    event NFTPurchased(uint256 indexed tokenId, address indexed seller, uint256 cost, uint256 ask);
    event NFTSold(uint256 indexed tokenId, address indexed buyer, address indexed recipient, uint256 proceeds);
    event BuybackBurned(uint256 ethSpent, uint256 tokensBurned);

    constructor(Config memory c) {
        if (c.token.code.length == 0 || c.collection.code.length == 0 || c.market.code.length == 0
            || c.initializer == address(0) || c.tokenCount == 0 || c.tokenCount > 512
            || c.firstTokenId > type(uint256).max - c.tokenCount
            || (c.maxSpendPerEpoch != 0 && c.maxPurchasePrice > c.maxSpendPerEpoch)
            || c.epochDuration < 1 hours || c.minPurchaseInterval < 1 minutes
            || c.maxInventory == 0 || c.maxInventory > c.tokenCount
            || c.maxBuybackAmount == 0 || c.minBuybackInterval < 1 minutes
            || IRevisionedNFTMarket(c.market).collection() != c.collection) revert InvalidConfig();
        token = IBurnableStrategyToken(c.token);
        collection = IERC721(c.collection);
        market = IRevisionedNFTMarket(c.market);
        initializer = c.initializer;
        firstTokenId = c.firstTokenId;
        tokenCount = c.tokenCount;
        maxPurchasePrice = c.maxPurchasePrice;
        maxSpendPerEpoch = c.maxSpendPerEpoch;
        epochDuration = c.epochDuration;
        minPurchaseInterval = c.minPurchaseInterval;
        maxInventory = c.maxInventory;
        maxBuybackAmount = c.maxBuybackAmount;
        minBuybackInterval = c.minBuybackInterval;
    }

    function initializeHook(address hook_) external {
        if (msg.sender != initializer) revert Unauthorized();
        if (address(hook) != address(0)) revert AlreadyInitialized();
        if (hook_.code.length == 0 || IStrategyExecutor(hook_).token() != address(token)
            || IStrategyExecutor(hook_).treasury() != address(this)) revert InvalidConfig();
        hook = IStrategyExecutor(hook_);
        emit Initialized(hook_);
    }

    function recordFees() external payable {
        if (msg.sender != address(hook) || msg.sender == address(0)) revert Unauthorized();
        acquisitionBalance += msg.value;
        totalFeesReceived += msg.value;
        emit FeesReceived(msg.value);
    }

    /// @notice Direct donations and Claus NFT holding rewards fund subsequent purchases.
    receive() external payable {
        acquisitionBalance += msg.value;
        emit AcquisitionFunded(msg.sender, msg.value);
    }

    /// @notice Forced ETH can only be assigned to acquisitions, never sent to a caller.
    function accountSurplus() external {
        uint256 surplus = address(this).balance - acquisitionBalance - buybackBalance;
        acquisitionBalance += surplus;
        emit AcquisitionFunded(address(0), surplus);
    }

    /// @notice Minimum among active quotes exposed by the fixed acquisition market.
    /// @dev The OpenSea adapter exposes the trusted bot's atomic candidate only.
    ///      This does not prove an OpenSea/global floor or fair market value.
    function cheapestListing() public view returns (Quote memory q) {
        uint256 end = firstTokenId + tokenCount;
        for (uint256 id = firstTokenId; id < end; ++id) {
            if (positions[id].ask != 0 || !market.isActive(id)) continue;
            (address seller, uint256 price,, uint256 revision) = market.listings(id);
            if (seller == address(this) || price == 0 || (maxPurchasePrice != 0 && price > maxPurchasePrice)) continue;
            if (!q.found || price < q.price) q = Quote(id, seller, price, revision, true);
        }
    }

    /// @notice Buy an eligible market quote; OpenSea quote selection is restricted by its adapter.
    function purchaseCheapest(uint256 expectedTokenId, uint256 expectedRevision) external nonReentrant {
        if (address(hook) == address(0)) revert Inactive();
        if (block.timestamp < nextPurchaseAt) revert Cooldown();
        Quote memory q = cheapestListing();
        if (!q.found) revert NoEligibleListing();
        if (q.tokenId != expectedTokenId || q.revision != expectedRevision) revert StaleQuote();
        uint256 epoch = block.timestamp / epochDuration;
        uint256 spent = epoch == spendEpoch ? spentInEpoch : 0;
        if (q.price > acquisitionBalance || (maxSpendPerEpoch != 0 && spent + q.price > maxSpendPerEpoch)
            || inventoryCount >= maxInventory) revert PurchaseLimit();

        acquisitionBalance -= q.price;
        totalAcquisitionSpent += q.price;
        spentInEpoch = spent + q.price;
        spendEpoch = epoch;
        nextPurchaseAt = block.timestamp + minPurchaseInterval;
        inventoryCount++;
        uint256 ask = Math.mulDiv(q.price, RESALE_BPS, 10_000, Math.Rounding.Ceil);
        positions[q.tokenId] = Position(q.price, ask);
        acquiring = true;
        pendingTokenId = q.tokenId;
        market.buy{value: q.price}(q.tokenId, q.revision, q.seller);
        acquiring = false;
        if (collection.ownerOf(q.tokenId) != address(this)) revert InvalidNFT();
        emit NFTPurchased(q.tokenId, q.seller, q.price, ask);
    }

    /// @notice Always available at exactly 1.1x acquisition cost, rounded up to a wei.
    /// @dev No marketplace approval is granted. Only this paid endpoint transfers an NFT out.
    function buyNFT(uint256 id, address recipient) external payable nonReentrant {
        uint256 ask = positions[id].ask;
        if (ask == 0 || msg.value != ask || recipient == address(0) || recipient == address(this)) revert InvalidPayment();
        delete positions[id];
        inventoryCount--;
        buybackBalance += msg.value;
        totalSaleProceeds += msg.value;
        collection.safeTransferFrom(address(this), recipient, id);
        emit NFTSold(id, msg.sender, recipient, msg.value);
    }

    /// @notice Public, bounded batches. Executor determines the immutable TWAP slippage bound.
    function executeBuyback() external nonReentrant returns (uint256 burned) {
        if (address(hook) == address(0)) revert Inactive();
        if (block.timestamp < nextBuybackAt) revert Cooldown();
        uint256 amount = Math.min(buybackBalance, maxBuybackAmount);
        if (amount == 0) revert InvalidBuyback();
        nextBuybackAt = block.timestamp + minBuybackInterval;
        buybackBalance -= amount;
        uint256 beforeBalance = token.balanceOf(address(this));
        uint256 reported = hook.executeBuyback{value: amount}();
        burned = token.balanceOf(address(this)) - beforeBalance;
        if (burned == 0 || burned != reported) revert InvalidBuyback();
        uint256 supplyBefore = token.totalSupply();
        token.burn(burned);
        if (token.totalSupply() != supplyBefore - burned || token.balanceOf(address(this)) != beforeBalance) revert InvalidBuyback();
        totalBuybackSpent += amount;
        totalTokensBurned += burned;
        emit BuybackBurned(amount, burned);
    }

    function onERC721Received(address, address, uint256 id, bytes calldata) external view returns (bytes4) {
        if (msg.sender != address(collection) || !acquiring || id != pendingTokenId) revert InvalidNFT();
        return IERC721Receiver.onERC721Received.selector;
    }
}
","keccak256":"0x9b35a47c21c38d299ac4590ac037130130f50b3bafed3e9eb10b48d40e8a65b2","license":"MIT"},"contracts/StrategyV4Hook.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {ModifyLiquidityParams, SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {BeforeSwapDelta, toBeforeSwapDelta} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {IStrategyBuyback} from "./interfaces/IStrategyBuyback.sol";
import {StrategyOracle} from "./libraries/StrategyOracle.sol";

interface IStrategyFeeReceiver {
    function recordFees() external payable;
}

/// @notice Immutable, single-pool ETH trading fees and treasury-only TWAP-bounded buybacks.
/// @dev Requires a CREATE2 address whose low 14 bits equal 0x30cc. No owner,
/// setters, arbitrary call targets, token approvals, or asset withdrawal functions.
/// User routes must use exact input. Buys must consume their full input after tax.
contract StrategyV4Hook is IHooks, IUnlockCallback, IStrategyBuyback {
    using PoolIdLibrary for PoolKey;
    using BalanceDeltaLibrary for BalanceDelta;
    using StateLibrary for IPoolManager;
    using StrategyOracle for StrategyOracle.State;

    uint24 public constant POOL_FEE = 0;
    int24 public constant TICK_SPACING = 60;
    uint160 public constant REQUIRED_HOOK_FLAGS = 0x30cc;
    uint256 private constant BPS = 10_000;

    IPoolManager public immutable poolManager;
    address public immutable token;
    address public immutable treasury;
    address public immutable poolInitializer;
    uint16 public immutable feeBps;
    uint32 public immutable twapWindow;
    uint16 public immutable maxSlippageBps;

    StrategyOracle.State private _oracle;
    // 0 = idle, 1 = buyback, 2 = realize fee claims after the trader has settled.
    uint8 private _operation;
    uint256 public pendingFees;

    error InvalidConfiguration();
    error OnlyPoolManager();
    error OnlyTreasury();
    error OnlyInitializer();
    error WrongPool();
    error ExactInputOnly();
    error InvalidAmount();
    error PartialFill();
    error SlippageExceeded(uint256 received, uint256 minimum);
    error UnexpectedCallback();
    error HookNotEnabled();

    event TradingFeeCollected(bool indexed buy, uint256 amount);
    event FeesFlushed(uint256 amount);
    event BuybackExecuted(uint256 ethSpent, uint256 tokensReceived, uint256 minimumOut);

    constructor(
        IPoolManager manager,
        address token_,
        address treasury_,
        address poolInitializer_,
        uint16 feeBps_,
        uint32 twapWindow_,
        uint16 maxSlippageBps_
    ) {
        if (
            address(manager).code.length == 0 || token_ == address(0) || treasury_ == address(0)
                || poolInitializer_ == address(0) || feeBps_ == 0 || feeBps_ > 1000
                || twapWindow_ < 1800 || twapWindow_ > 3600 || maxSlippageBps_ > 1000
        ) revert InvalidConfiguration();
        poolManager = manager;
        token = token_;
        treasury = treasury_;
        poolInitializer = poolInitializer_;
        feeBps = feeBps_;
        twapWindow = twapWindow_;
        maxSlippageBps = maxSlippageBps_;
        Hooks.validateHookPermissions(IHooks(address(this)), getHookPermissions());
    }

    modifier onlyManager() {
        if (msg.sender != address(poolManager)) revert OnlyPoolManager();
        _;
    }

    receive() external payable onlyManager {}

    function getHookPermissions() public pure returns (Hooks.Permissions memory permissions) {
        permissions.beforeInitialize = true;
        permissions.afterInitialize = true;
        permissions.beforeSwap = true;
        permissions.afterSwap = true;
        permissions.beforeSwapReturnDelta = true;
        permissions.afterSwapReturnDelta = true;
    }

    function getPoolKey() public view returns (PoolKey memory) {
        return PoolKey(Currency.wrap(address(0)), Currency.wrap(token), POOL_FEE, TICK_SPACING, IHooks(address(this)));
    }

    /// @notice Derived from immutable configuration, including this hook's CREATE2 address.
    function poolId() public view returns (PoolId) {
        return getPoolKey().toId();
    }

    function beforeInitialize(address sender, PoolKey calldata key, uint160)
        external view onlyManager returns (bytes4)
    {
        _checkPool(key);
        if (sender != poolInitializer) revert OnlyInitializer();
        return IHooks.beforeInitialize.selector;
    }

    function afterInitialize(address, PoolKey calldata key, uint160, int24 tick)
        external onlyManager returns (bytes4)
    {
        _checkPool(key);
        _oracle.write(tick);
        return IHooks.afterInitialize.selector;
    }

    function beforeSwap(address sender, PoolKey calldata key, SwapParams calldata params, bytes calldata)
        external onlyManager returns (bytes4, BeforeSwapDelta, uint24)
    {
        _checkPool(key);
        uint256 amount = _exactInputAmount(params.amountSpecified);
        uint256 fee;
        if (params.zeroForOne && sender != address(this)) {
            fee = Math.mulDiv(amount, feeBps, BPS);
            _accrueFee(fee, true);
        }
        return (IHooks.beforeSwap.selector, toBeforeSwapDelta(int128(uint128(fee)), 0), 0);
    }

    function afterSwap(
        address sender,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata
    ) external onlyManager returns (bytes4, int128) {
        _checkPool(key);
        uint256 amount = _exactInputAmount(params.amountSpecified);
        _recordCurrentTick();
        uint256 fee;
        if (sender != address(this)) {
            if (params.zeroForOne) {
                // Charging specified ETH before the swap is safe only when all of
                // the remaining input is used. Partial fills revert atomically.
                uint256 expected = amount - Math.mulDiv(amount, feeBps, BPS);
                if (delta.amount0() >= 0 || uint256(-int256(delta.amount0())) != expected) revert PartialFill();
            } else if (delta.amount0() > 0) {
                fee = Math.mulDiv(uint128(delta.amount0()), feeBps, BPS);
                _accrueFee(fee, false);
            }
        }
        return (IHooks.afterSwap.selector, int128(uint128(fee)));
    }

    /// @notice The minimum output is fixed by this pool's historical ticks, not a keeper quote.
    /// @dev Includes the static LP fee and immutable slippage allowance. A future
    /// PoolManager protocol fee can make execution more restrictive, never less.
    function minimumBuybackOut(uint256 amountIn) public view returns (uint256 amountOut) {
        if (amountIn == 0 || amountIn > uint256(uint128(type(int128).max))) revert InvalidAmount();
        int24 meanTick = _oracle.consult(twapWindow);
        uint256 afterPoolFee = Math.mulDiv(amountIn, 1_000_000 - POOL_FEE, 1_000_000);
        uint256 quote = StrategyOracle.quoteToken1(meanTick, afterPoolFee);
        amountOut = Math.mulDiv(quote, BPS - maxSlippageBps, BPS);
        if (amountOut == 0) revert InvalidAmount();
    }

    function consultTick() external view returns (int24) {
        return _oracle.consult(twapWindow);
    }

    function oracleState() external view returns (uint16 newest, uint16 count) {
        return (_oracle.newest, _oracle.count);
    }

    function executeBuyback() external payable returns (uint256 amountOut) {
        if (msg.sender != treasury) revert OnlyTreasury();
        if (_operation != 0) revert UnexpectedCallback();
        uint256 minimum = minimumBuybackOut(msg.value);
        _operation = 1;
        amountOut = abi.decode(poolManager.unlock(abi.encode(msg.value, minimum)), (uint256));
        _operation = 0;
        emit BuybackExecuted(msg.value, amountOut, minimum);
    }

    function unlockCallback(bytes calldata data) external onlyManager returns (bytes memory) {
        if (_operation == 2) {
            uint256 amount = abi.decode(data, (uint256));
            poolManager.burn(address(this), 0, amount);
            poolManager.take(Currency.wrap(address(0)), address(this), amount);
            IStrategyFeeReceiver(treasury).recordFees{value: amount}();
            return bytes("");
        }
        if (_operation != 1) revert UnexpectedCallback();
        (uint256 amountIn, uint256 minimum) = abi.decode(data, (uint256, uint256));
        BalanceDelta delta = poolManager.swap(
            getPoolKey(),
            SwapParams({
                zeroForOne: true,
                amountSpecified: -int256(amountIn),
                sqrtPriceLimitX96: TickMath.MIN_SQRT_PRICE + 1
            }),
            bytes("")
        );
        if (delta.amount0() >= 0 || uint256(-int256(delta.amount0())) != amountIn) revert PartialFill();
        if (delta.amount1() <= 0) revert SlippageExceeded(0, minimum);
        uint256 amountOut = uint128(delta.amount1());
        if (amountOut < minimum) revert SlippageExceeded(amountOut, minimum);

        // v4 deliberately skips callbacks when the hook is the swap sender.
        _recordCurrentTick();
        poolManager.sync(Currency.wrap(address(0)));
        poolManager.settle{value: amountIn}();
        poolManager.take(Currency.wrap(token), treasury, amountOut);
        return abi.encode(amountOut);
    }

    /// @notice Anyone may realize accrued native claims; ETH can only reach the treasury.
    /// @dev This must run after the trade unlock completes, not inside its callbacks.
    function flushFees() external {
        if (_operation != 0) revert UnexpectedCallback();
        uint256 amount = pendingFees;
        if (amount == 0) return;
        pendingFees = 0;
        _operation = 2;
        poolManager.unlock(abi.encode(amount));
        _operation = 0;
        emit FeesFlushed(amount);
    }

    function _accrueFee(uint256 fee, bool buy) private {
        if (fee == 0) return;
        // Taking ETH now would rely on unrelated pool balances on the first trade.
        // Claims balance our hook delta without requiring the input to be settled yet.
        poolManager.mint(address(this), 0, fee);
        pendingFees += fee;
        emit TradingFeeCollected(buy, fee);
    }

    function _recordCurrentTick() private {
        (, int24 tick,,) = poolManager.getSlot0(poolId());
        _oracle.write(tick);
    }

    function _checkPool(PoolKey calldata key) private view {
        if (PoolId.unwrap(key.toId()) != PoolId.unwrap(poolId())) revert WrongPool();
    }

    function _exactInputAmount(int256 specified) private pure returns (uint256 amount) {
        if (specified >= 0) revert ExactInputOnly();
        if (specified < -int256(type(int128).max)) revert InvalidAmount();
        amount = uint256(-specified);
    }

    // Disabled hooks deliberately fail closed if called outside their declared mask.
    function beforeAddLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external pure returns (bytes4) { revert HookNotEnabled(); }
    function afterAddLiquidity(
        address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata
    ) external pure returns (bytes4, BalanceDelta) { revert HookNotEnabled(); }
    function beforeRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external pure returns (bytes4) { revert HookNotEnabled(); }
    function afterRemoveLiquidity(
        address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata
    ) external pure returns (bytes4, BalanceDelta) { revert HookNotEnabled(); }
    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata)
        external pure returns (bytes4) { revert HookNotEnabled(); }
    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata)
        external pure returns (bytes4) { revert HookNotEnabled(); }
}
